import java.util.Comparator;
import java.util.List;
public final class Sorts {
    // Contract: return sorted values without modifying caller input.
    // Null elements are disallowed; input may be unmodifiable.
    public List<String> sortedCopy(List<String> input) {
        input.sort(Comparator.naturalOrder());
        return input;
    }
}

